import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Activity, AlertTriangle, ArrowDownToLine, ArrowUpRight, BarChart3, BookOpenCheck, Bot, CheckCircle2, ChevronRight, CircleHelp, ClipboardList, Database, FileText, FolderOpen, Gauge, GitBranch, Layers3, Plus, RefreshCw, Search, ShieldCheck, Sparkles, UploadCloud, Workflow, Users, ClipboardCheck, ListChecks } from 'lucide-react';
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { API, jsonOptions, request, uploadOptions } from './api.js';

const NAV = [
  { id: 'overview', label: 'Overview', icon: BarChart3 },
  { id: 'casework', label: 'Full DMAIC case run', icon: ClipboardCheck },
  { id: 'analysis', label: 'Data & analysis', icon: Activity },
  { id: 'projects', label: 'DMAIC projects', icon: Workflow },
  { id: 'agent', label: 'AI analyst', icon: Bot },
  { id: 'team', label: 'Virtual Six Sigma team', icon: Users },
  { id: 'evidence', label: 'Evidence & audit', icon: ShieldCheck },
];
const PHASES = ['Define', 'Measure', 'Analyze', 'Improve', 'Control'];

function Card({ children, className = '' }) { return <section className={`card ${className}`}>{children}</section>; }
function SectionTitle({ eyebrow, title, detail, action }) { return <div className="section-title"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h2>{title}</h2>{detail && <p>{detail}</p>}</div>{action}</div>; }
function Metric({ label, value, sub, icon: Icon, accent = false }) { return <Card className={`metric ${accent ? 'metric-accent' : ''}`}><div className="metric-top"><span>{label}</span>{Icon && <span className="metric-icon"><Icon size={17}/></span>}</div><div className="metric-value">{value ?? '—'}</div>{sub && <div className="metric-sub">{sub}</div>}</Card>; }
function Empty({ icon: Icon = FolderOpen, title, detail }) { return <div className="empty"><span className="empty-icon"><Icon size={23}/></span><strong>{title}</strong><p>{detail}</p></div>; }
function Status({ children }) { return <span className={`status status-${String(children).toLowerCase().replace(/\s+/g, '-')}`}>{children}</span>; }
function Field({ label, children, hint }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function DownloadLink({ href, children }) { return <a className="button button-secondary button-small" href={href} target="_blank" rel="noreferrer"><ArrowDownToLine size={15}/>{children}</a>; }

export default function App() {
  const [page, setPage] = useState('overview');
  const [health, setHealth] = useState(null);
  const [dashboard, setDashboard] = useState(null);
  const [projects, setProjects] = useState([]);
  const [datasets, setDatasets] = useState([]);
  const [documents, setDocuments] = useState([]);
  const [audit, setAudit] = useState([]);
  const [agentRuns, setAgentRuns] = useState([]);
  const [selectedDataset, setSelectedDataset] = useState('');
  const [analysisConfig, setAnalysisConfig] = useState({ value_column: '', lsl: '', usl: '', defective_column: '', defect_count_column: '', opportunities_per_unit: '', group_column: '', group_a: '', group_b: '' });
  const [analysis, setAnalysis] = useState(null);
  const [analysisRuns, setAnalysisRuns] = useState([]);
  const [selectedProject, setSelectedProject] = useState('');
  const [projectForm, setProjectForm] = useState({ name: '', process_name: '', problem_statement: '', goal_statement: '', owner: '', priority: 'Medium', target_date: '' });
  const [entryForm, setEntryForm] = useState({ phase: 'Define', entry_type: 'note', title: '', content: '' });
  const [agentPrompt, setAgentPrompt] = useState('Analyze this process, identify what the evidence supports, list hypotheses separately, and recommend the next DMAIC actions.');
  const [agentResult, setAgentResult] = useState(null);
  const [teamReview, setTeamReview] = useState(null);
  const [teamHistory, setTeamHistory] = useState([]);
  const [caseFiles, setCaseFiles] = useState([]);
  const [casePrompt, setCasePrompt] = useState('Act as the complete cross-functional Six Sigma team. Read every supplied charter, task prompt, data dictionary, reference document, baseline dataset, context dataset, measurement-system study, pilot, post-change dataset, control dataset, and financial model. Map each file to its role. Calculate all supported metrics from raw data, cross-check calculations, validate defect flags against specifications, analyze associations without claiming causation, evaluate the pilot and pre/post evidence, calculate SPC and financial forecasts, identify missing evidence and limitations, and produce a complete actionable DMAIC report. Clearly label calculated facts, assumptions, hypotheses, recommendations, and forecasts. Never invent missing evidence.');
  const [caseResult, setCaseResult] = useState(null);
  const [teamQuestion, setTeamQuestion] = useState('Act as the full cross-functional Six Sigma team. Review the project, challenge assumptions, identify blockers, create a prioritized action plan, and specify the evidence needed to pass each DMAIC gate.');
  const [documentQuery, setDocumentQuery] = useState('');
  const [manualFilename, setManualFilename] = useState('manual-data.csv');
  const [manualCSV, setManualCSV] = useState('');
  const [connectorUrl, setConnectorUrl] = useState('');
  const [connectorToken, setConnectorToken] = useState('');
  const [connectorFilename, setConnectorFilename] = useState('connected-source.csv');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const refresh = useCallback(async () => {
    setError('');
    try {
      const [h, d, p, ds, docs, logs, runs, savedAnalyses, savedTeamReviews] = await Promise.all([
        request('/health'), request('/dashboard'), request('/projects'), request('/datasets'), request('/documents'), request('/audit?limit=30'), request('/agent/runs'), request('/analyses'), request('/team/reviews')
      ]);
      setHealth(h); setDashboard(d); setProjects(p); setDatasets(ds); setDocuments(docs); setAudit(logs); setAgentRuns(runs); setAnalysisRuns(savedAnalyses); setTeamHistory(savedTeamReviews);
      if (!selectedProject && p.length) setSelectedProject(p[0].id);
      if (!selectedDataset && ds.length) setSelectedDataset(ds[0].id);
    } catch (e) { setError(`Could not connect to the API. Start the backend and refresh. ${e.message}`); }
  }, [selectedProject, selectedDataset]);

  useEffect(() => { refresh(); }, [refresh]);
  const currentProject = useMemo(() => projects.find(p => p.id === selectedProject), [projects, selectedProject]);
  const currentDataset = useMemo(() => datasets.find(d => d.id === selectedDataset), [datasets, selectedDataset]);

  async function runBusy(action, successText) {
    setBusy(true); setError(''); setNotice('');
    try { await action(); if (successText) setNotice(successText); await refresh(); }
    catch (e) { setError(e.message || 'Something went wrong.'); }
    finally { setBusy(false); }
  }

  async function onUpload(file) {
    if (!file) return;
    await runBusy(async () => {
      const result = await request('/files/upload', uploadOptions(file));
      if (result.kind === 'dataset') {
        setAnalysis(null); setSelectedDataset(result.id);
        const numeric = result.columns.find(c => result.preview.some(row => typeof row[c] === 'number')) || result.columns[0] || '';
        setAnalysisConfig(c => ({ ...c, value_column: numeric, lsl: '', usl: '', defective_column: '', defect_count_column: '', opportunities_per_unit: '', group_column: '', group_a: '', group_b: '' }));
        setNotice(`Imported ${result.filename}. Choose analysis settings and run the analysis.`);
      } else setNotice(`Indexed ${result.filename} as a searchable evidence document.`);
    });
  }

  async function importManualData(e) {
    e.preventDefault();
    await runBusy(async () => {
      const result = await request('/datasets/manual-csv', jsonOptions('POST', { filename: manualFilename, csv_text: manualCSV }));
      setAnalysis(null); setSelectedDataset(result.id);
      const numeric = result.columns.find(c => result.preview.some(row => typeof row[c] === 'number')) || result.columns[0] || '';
      setAnalysisConfig(c => ({ ...c, value_column: numeric }));
      setManualCSV(''); setNotice(`Imported manual dataset ${result.filename}.`);
    });
  }

  async function importConnector(e) {
    e.preventDefault();
    await runBusy(async () => {
      const result = await request('/connectors/http-json/import', jsonOptions('POST', { url: connectorUrl, bearer_token: connectorToken, filename: connectorFilename }));
      setAnalysis(null); setSelectedDataset(result.id);
      const numeric = result.columns.find(c => result.preview.some(row => typeof row[c] === 'number')) || result.columns[0] || '';
      setAnalysisConfig(c => ({ ...c, value_column: numeric }));
      setConnectorToken(''); setNotice(`Imported ${result.filename} from the read-only HTTPS connector. Credentials were not stored.`);
    });
  }

  async function runAnalysis() {
    if (!selectedDataset) throw new Error('Upload or select a dataset first.');
    const body = { value_column: analysisConfig.value_column };
    if (analysisConfig.lsl !== '' || analysisConfig.usl !== '') { body.lsl = analysisConfig.lsl === '' ? null : Number(analysisConfig.lsl); body.usl = analysisConfig.usl === '' ? null : Number(analysisConfig.usl); }
    if (analysisConfig.defective_column) body.defective_column = analysisConfig.defective_column;
    if (analysisConfig.defect_count_column) { body.defect_count_column = analysisConfig.defect_count_column; if (analysisConfig.opportunities_per_unit !== '') body.opportunities_per_unit = Number(analysisConfig.opportunities_per_unit); }
    if (analysisConfig.group_column && analysisConfig.group_a && analysisConfig.group_b) { body.group_column = analysisConfig.group_column; body.group_a = analysisConfig.group_a; body.group_b = analysisConfig.group_b; }
    await runBusy(async () => { const out = await request(`/datasets/${selectedDataset}/analysis`, jsonOptions('POST', body)); setAnalysis(out); setNotice('Analysis completed. Review assumptions before interpreting capability or diagnostic metrics.'); }, '');
  }

  async function createProject(e) {
    e.preventDefault();
    await runBusy(async () => {
      const p = await request('/projects', jsonOptions('POST', projectForm));
      setProjectForm({ name: '', process_name: '', problem_statement: '', goal_statement: '', owner: '', priority: 'Medium', target_date: '' });
      setSelectedProject(p.id); setNotice('DMAIC project created. Add evidence and decisions as the work progresses.');
    });
  }

  async function addEntry(e) {
    e.preventDefault();
    if (!selectedProject) throw new Error('Create or select a project first.');
    await runBusy(async () => {
      await request(`/projects/${selectedProject}/entries`, jsonOptions('POST', entryForm));
      setEntryForm(f => ({ ...f, title: '', content: '' })); setNotice('DMAIC log entry saved.');
      const updated = await request(`/projects/${selectedProject}`); setProjects(ps => ps.map(p => p.id === updated.id ? updated : p));
    });
  }

  async function runCaseWorkspace(e) {
    e.preventDefault();
    if (!caseFiles.length) throw new Error('Upload a ZIP evidence package or multiple datasets and reference files first.');
    await runBusy(async () => {
      const form = new FormData();
      caseFiles.forEach(file => form.append('files', file));
      form.append('prompt', casePrompt);
      const out = await request('/case-workspace/run', { method: 'POST', body: form });
      setCaseResult(out.report);
      setNotice(`Complete DMAIC case review finished. Parsed ${out.report.data_provenance.parsed_data_tables} data tables and indexed ${out.report.data_provenance.documents_indexed} reference documents.`);
    });
  }

  async function runAgent(e) {
    e.preventDefault();
    if (!selectedProject && !selectedDataset && !analysis) throw new Error('Create a project or select a dataset to ground the agent.');
    await runBusy(async () => {
      const out = await request('/agent/run', jsonOptions('POST', { project_id: selectedProject || null, dataset_id: selectedDataset || null, analysis_run_id: analysis?.id || null, prompt: agentPrompt }));
      setAgentResult(out); setNotice('DMAIC agent run completed. Calculated findings and AI interpretation are separated.');
    });
  }

  async function runTeamReview(e) {
    e.preventDefault();
    if (!selectedProject && !selectedDataset && !analysis) throw new Error('Select a DMAIC project or dataset so the virtual team has something concrete to review.');
    await runBusy(async () => {
      const out = await request('/team/review', jsonOptions('POST', {
        project_id: selectedProject || null,
        dataset_id: selectedDataset || null,
        analysis_run_id: analysis?.id || null,
        question: teamQuestion,
      }));
      setTeamReview(out);
      setNotice('Virtual Six Sigma team review completed. Stage gates are recommendations for human review, not approvals.');
    });
  }

  async function openTeamReview(reviewId) {
    try { setTeamReview(await request(`/team/reviews/${reviewId}`)); setPage('team'); }
    catch (e) { setError(e.message); }
  }

  async function updateTeamAction(actionId, status) {
    if (!teamReview) return;
    await runBusy(async () => {
      const updated = await request(`/team/reviews/${teamReview.review_id}/actions/${actionId}`, jsonOptions('PATCH', { status }));
      setTeamReview(updated);
      setNotice(`${actionId} updated to ${status.replaceAll('_', ' ')}.`);
    });
  }

  async function searchDocuments(e) {
    e?.preventDefault();
    try { setDocuments(await request(`/documents?q=${encodeURIComponent(documentQuery)}`)); }
    catch (e) { setError(e.message); }
  }

  async function openAnalysis(analysisId) {
    try {
      const saved = await request(`/analysis/${analysisId}`);
      setSelectedDataset(saved.dataset_id); setAnalysis(saved); setPage('analysis');
    } catch (e) { setError(e.message); }
  }

  async function resumeAgent(runId) {
    await runBusy(async () => {
      const resumed = await request(`/agent/runs/${runId}/resume`, jsonOptions('POST', {}));
      setAgentResult(resumed); setNotice('Saved agent run resumed successfully.');
    });
  }

  async function openRun(runId) {
    try { const result = await request(`/agent/runs/${runId}`); setAgentResult(result); setPage('agent'); }
    catch (e) { setError(e.message); }
  }

  const numericColumns = currentDataset?.columns || [];
  const phaseCounts = dashboard?.project_status_counts || {};

  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark"><Activity size={23}/></div><div><div className="brand-name">SigmaPilot</div><div className="brand-caption">PROCESS INTELLIGENCE</div></div></div>
      <div className="workspace"><span className="workspace-dot"/> LOCAL WORKSPACE <span className="workspace-chevron">⌄</span></div>
      <div className="nav-label">WORKSPACE</div>
      <nav>{NAV.map(item => { const Icon = item.icon; return <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={() => setPage(item.id)}><Icon size={18}/><span>{item.label}</span>{page === item.id && <ChevronRight className="nav-arrow" size={15}/>}</button>; })}</nav>
      <div className="sidebar-bottom"><div className="privacy-card"><ShieldCheck size={17}/><div><strong>Local-first by default</strong><p>Files and project records stay on this machine. Only the configured model request is sent to your provider.</p></div></div><div className="api-state"><span className={`state-dot ${health?.llm_configured ? 'online' : ''}`}/><span>{health?.llm_configured ? 'AI provider configured' : 'AI key not configured'}</span><span className="api-state-right">{health?.database === 'ok' ? 'DB OK' : '—'}</span></div><div className="sidebar-footer">SigmaPilot prototype <span>v1.1.0</span></div></div>
    </aside>

    <main className="main-area">
      <header className="topbar"><div className="breadcrumbs"><span>Workspace</span><ChevronRight size={14}/><strong>{NAV.find(n => n.id === page)?.label || 'Overview'}</strong></div><div className="top-actions"><span className="connection"><span className={`state-dot ${health?.status === 'ok' ? 'online' : ''}`}/>{health?.status === 'ok' ? 'API connected' : 'Connecting'}</span><button className="icon-button" onClick={refresh} title="Refresh"><RefreshCw size={17}/></button><div className="avatar">SP</div></div></header>
      <div className="page-content">
        {error && <div className="alert alert-error"><AlertTriangle size={18}/><span>{error}</span><button onClick={() => setError('')}>Dismiss</button></div>}
        {notice && <div className="alert alert-success"><CheckCircle2 size={18}/><span>{notice}</span><button onClick={() => setNotice('')}>Dismiss</button></div>}

        {page === 'overview' && <>
          <div className="hero-row"><div><div className="eyebrow"><span className="eyebrow-line"/> YOUR CONTINUOUS IMPROVEMENT HUB</div><h1>Make every process<br/><span>measurably better.</span></h1><p className="hero-copy">Turn process data into defensible decisions. Analyze the evidence, manage DMAIC work, and keep assumptions visible.</p><div className="hero-actions"><button className="button button-primary" onClick={() => setPage('analysis')}><UploadCloud size={17}/> Analyze process data</button><button className="button button-secondary" onClick={() => setPage('projects')}><Plus size={17}/> Start DMAIC project</button></div></div><div className="hero-visual"><div className="visual-orbit orbit-one"/><div className="visual-orbit orbit-two"/><div className="visual-center"><Gauge size={42}/><span>DMAIC</span></div><div className="visual-node node-a"><Database size={16}/></div><div className="visual-node node-b"><BarChart3 size={16}/></div><div className="visual-node node-c"><Bot size={16}/></div><div className="visual-label label-a">DATA</div><div className="visual-label label-b">INSIGHT</div><div className="visual-label label-c">ACTION</div></div></div>
          <div className="section-heading-row"><div><h2>Workspace at a glance</h2><p>Live counts from your local project store</p></div><span className="live-pill"><span className="state-dot online"/> LIVE DATA</span></div>
          <div className="metric-grid"><Metric label="Active DMAIC projects" value={(phaseCounts.Define || 0)+(phaseCounts.Measure || 0)+(phaseCounts.Analyze || 0)+(phaseCounts.Improve || 0)+(phaseCounts.Control || 0)} sub="Across all active phases" icon={Workflow} accent/><Metric label="Datasets indexed" value={dashboard?.datasets ?? '—'} sub="CSV and Excel data" icon={Database}/><Metric label="Analysis runs" value={dashboard?.analysis_runs ?? '—'} sub="Reproducible calculations" icon={Activity}/><Metric label="Evidence documents" value={dashboard?.documents ?? '—'} sub="PDF, DOCX, TXT, Markdown" icon={FileText}/></div>
          <div className="overview-grid"><Card><div className="card-heading"><div><h3>DMAIC portfolio</h3><p>Projects grouped by current phase</p></div><button className="text-button" onClick={() => setPage('projects')}>Manage projects <ArrowUpRight size={14}/></button></div>{Object.keys(phaseCounts).length ? <div className="portfolio-chart"><ResponsiveContainer width="100%" height="210"><BarChart data={PHASES.map(name => ({ name, projects: phaseCounts[name] || 0 }))} margin={{top: 10, right: 12, left: -20, bottom: 0}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#27323d"/><XAxis dataKey="name" tick={{fill:'#8996a6',fontSize:12}} axisLine={false} tickLine={false}/><YAxis allowDecimals={false} tick={{fill:'#8996a6',fontSize:12}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'#151d26',border:'1px solid #2d3a48',borderRadius:10,color:'#f3f6fa'}}/><Bar dataKey="projects" fill="#4cd6b0" radius={[5,5,0,0]} maxBarSize={35}/></BarChart></ResponsiveContainer></div> : <Empty icon={Workflow} title="Your project portfolio starts here" detail="Create a DMAIC project to track the process from problem definition to control."/>}</Card>
            <Card><div className="card-heading"><div><h3>Recent activity</h3><p>Audit trail of meaningful actions</p></div><button className="text-button" onClick={() => setPage('evidence')}>View all <ArrowUpRight size={14}/></button></div>{(dashboard?.recent_activity || []).length ? <div className="activity-list">{dashboard.recent_activity.slice(0,6).map((a,i)=><div className="activity-item" key={`${a.entity_id}-${i}`}><div className="activity-icon"><GitBranch size={15}/></div><div className="activity-main"><strong>{a.action.replaceAll('.', ' ')}</strong><span>{a.entity_type} · {a.entity_id.slice(0,8)}</span></div><time>{new Date(a.created_at).toLocaleDateString()}</time></div>)}</div> : <Empty icon={ClipboardList} title="No activity yet" detail="Uploads, analyses, and project updates will appear here."/>}</Card></div>
          <div className="principle-strip"><div className="principle-icon"><ShieldCheck size={20}/></div><div><strong>Evidence before confidence.</strong><p>Statistical findings are computed from your data. AI suggestions are explicitly labeled and never presented as measured outcomes.</p></div><span className="principle-tag">BUILT-IN EVIDENCE DISCIPLINE</span></div>
        </>}

        {page === 'casework' && <>
          <SectionTitle eyebrow="EVIDENCE PACK → FULL DMAIC" title="Run a complete Six Sigma case" detail="Upload an entire project pack at once—ZIP, CSVs, Excel workbooks, charter, task prompt, data dictionary, prior reports, measurement study, pilot, control data, and financial assumptions. SigmaPilot maps the files, calculates from raw data, and builds a traceable DMAIC work product." action={<span className={`provider-pill ${health?.llm_configured?'provider-on':''}`}><span className="state-dot"/>{health?.llm_configured?'Optional AI synthesis configured':'Deterministic evidence mode'}</span>}/>
          <div className="agent-layout"><div className="agent-main">
            <Card className="agent-run-card"><div className="agent-heading"><div className="agent-spark"><ClipboardCheck size={23}/></div><div><h3>1. Upload the complete evidence pack</h3><p>Upload one ZIP containing the whole project or select many files. The ZIP will be expanded and each supported file indexed by name, structure, and content.</p></div></div>
              <form className="stack-form" onSubmit={runCaseWorkspace}>
                <Field label="Project files (multiple files supported)" hint="CSV, TSV, XLSX, XLS, JSON, TXT, Markdown, PDF, DOCX, or ZIP. Maximum 35 MB total per run."><input type="file" multiple accept=".zip,.csv,.tsv,.xlsx,.xls,.json,.txt,.md,.rst,.pdf,.docx" onChange={e=>setCaseFiles(Array.from(e.target.files || []))} /></Field>
                {caseFiles.length > 0 && <div className="dataset-info"><div className="dataset-file"><FolderOpen size={20}/></div><div><strong>{caseFiles.length} selected file(s)</strong><span>{caseFiles.map(f=>f.name).join(' · ')}</span></div><button type="button" className="button button-secondary button-small" onClick={()=>setCaseFiles([])}>Clear</button></div>}
                <Field label="Task prompt / Six Sigma brief" hint="Use the supplied prompt or customize the expected deliverables. The prompt guides the analysis but does not override the data or evidence rules."><textarea rows="9" value={casePrompt} onChange={e=>setCasePrompt(e.target.value)}/></Field>
                <button className="button button-primary button-wide" disabled={busy || !caseFiles.length}><Sparkles size={17}/>{busy ? 'Auditing files and running DMAIC…' : 'Run full DMAIC case analysis'}</button>
              </form>
            </Card>
            {caseResult && <>
              <Card><div className="card-heading"><div><div className="eyebrow">CASE REPORT · {caseResult.run_id?.slice(0,8)}</div><h3>{caseResult.project_charter?.title || 'Complete DMAIC case review'}</h3><p>{caseResult.created_at ? new Date(caseResult.created_at).toLocaleString() : ''} · {caseResult.data_provenance?.synthetic_data_detected ? 'Synthetic data identified' : 'Dataset provenance requires confirmation'}</p></div><div className="heading-actions"><DownloadLink href={`${API}/reports/case/${caseResult.run_id}?format=markdown`}>Markdown</DownloadLink><DownloadLink href={`${API}/reports/case/${caseResult.run_id}?format=pdf`}>PDF report</DownloadLink><DownloadLink href={`${API}/reports/case/${caseResult.run_id}?format=json`}>JSON evidence</DownloadLink></div></div>
                <div className="audit-disclaimer"><AlertTriangle size={15}/><span>This is an evidence-led draft for review. Calculations are computed from supplied files; fishbone items and associations are not proven causes, and forecast savings are not realized savings.</span></div>
                <div className="metric-grid"><Metric label="Data tables parsed" value={caseResult.data_provenance?.parsed_data_tables ?? 0} sub={`${caseResult.data_provenance?.files_received ?? 0} uploaded file(s)`} icon={Database}/><Metric label="Baseline sample" value={caseResult.baseline_analysis?.n_valid ?? 'Blocked'} sub={caseResult.baseline_analysis?.status === 'calculated' ? `Mean ${caseResult.baseline_analysis.mean} · SD ${caseResult.baseline_analysis.sample_std_dev}` : caseResult.baseline_analysis?.reason} icon={Activity}/><Metric label="Baseline defect rate" value={caseResult.baseline_analysis?.specification?.defect_rate != null ? `${(caseResult.baseline_analysis.specification.defect_rate*100).toFixed(2)}%` : 'Not calculated'} sub={`${caseResult.baseline_analysis?.specification?.out_of_spec_count ?? '—'} observed out of spec`} icon={AlertTriangle}/><Metric label="Action items" value={caseResult.recommended_actions?.length ?? 0} sub="Prioritized with closure evidence" icon={ListChecks}/></div>
              </Card>
              <Card><div className="card-heading"><div><h3>File mapping and audit</h3><p>Review which inputs were parsed, skipped, or failed before trusting the analysis.</p></div></div><div className="audit-table-wrap"><table className="audit-table"><thead><tr><th>File</th><th>Role / kind</th><th>Status</th><th>Rows / details</th><th>Issues</th></tr></thead><tbody>{(caseResult.data_provenance?.file_inventory||[]).map((f,i)=><tr key={`${f.filename}-${i}`}><td>{f.filename}</td><td>{f.kind}</td><td><Status>{f.status}</Status></td><td>{f.rows ?? f.pages ?? f.chars ?? (f.sheets?.length ? `${f.sheets.length} sheets` : '—')}</td><td>{f.error || (f.columns?.join(', ') || f.sheets?.map(s=>s.name).join(', ') || '—')}</td></tr>)}</tbody></table></div></Card>
              <Card><div className="card-heading"><div><h3>DMAIC stage-gate review</h3><p>Each phase states what is available, what is blocked, and what evidence is needed to close the phase.</p></div></div><div className="team-gates">{(caseResult.dmaic_phase_review||[]).map((g,i)=><div className="team-gate" key={g.phase}><div className="team-gate-header"><div><span className="step-number">{i+1}</span><h4>{g.phase}</h4></div><Status>{g.status.replaceAll('_',' ')}</Status></div><strong>Next deliverables</strong><ul>{g.deliverables.map((x,j)=><li key={j}>{x}</li>)}</ul><strong>Exit evidence</strong><ul>{g.exit_evidence.map((x,j)=><li key={j}>{x}</li>)}</ul></div>)}</div></Card>
              <Card><div className="card-heading"><div><h3>Verified findings</h3><p>Claims grounded in calculated metrics or file-level checks.</p></div><span className="count-pill">{caseResult.verified_findings?.length || 0} findings</span></div>{caseResult.verified_findings?.length ? caseResult.verified_findings.map((f,i)=><div className="team-action" key={i}><div className="team-action-badge"><Status>{f.kind}</Status></div><div className="team-action-body"><h4>{f.claim}</h4><small><strong>Source:</strong> {f.source}</small></div></div>) : <p className="muted-text">No calculated findings were available. Review file mapping and missing inputs.</p>}</Card>
              <Card><div className="card-heading"><div><h3>Independent calculation validation</h3><p>Selected metrics are recomputed with separate arithmetic formulas over the same source rows.</p></div><Status>{caseResult.calculation_validation?.status || 'not checked'}</Status></div><div className="metric-grid"><Metric label="Checks performed" value={caseResult.calculation_validation?.check_count ?? 0} sub="Core arithmetic cross-checks" icon={ShieldCheck}/><Metric label="Failed checks" value={caseResult.calculation_validation?.failed_check_count ?? 0} sub="Must be investigated before use" icon={AlertTriangle}/></div><div className="audit-table-wrap"><table className="audit-table"><thead><tr><th>Metric</th><th>Source</th><th>Reported</th><th>Recomputed</th><th>Status</th></tr></thead><tbody>{(caseResult.calculation_validation?.checks||[]).map((c,i)=><tr key={i}><td>{c.metric}</td><td>{c.source}</td><td>{String(c.reported)}</td><td>{String(c.independently_recomputed)}</td><td><Status>{c.status}</Status></td></tr>)}</tbody></table></div><div className="assumption-box"><strong>Charter assumptions vs observed sample</strong><p>{caseResult.charter_assumption_validation?.note || 'No charter assumption could be reconciled.'}</p><p>Baseline assumption consistent with sample: {String(caseResult.charter_assumption_validation?.baseline_assumption_consistent_with_sample)} · Post sample at or below target: {String(caseResult.charter_assumption_validation?.post_sample_at_or_below_target)}</p></div></Card>
              <Card><div className="card-heading"><div><h3>Root-cause evidence and Pareto</h3><p>Association screens prioritize investigations; they do not establish causation.</p></div></div><div className="audit-table-wrap"><table className="audit-table"><thead><tr><th>Factor / category</th><th>Observed result</th><th>Test / source</th><th>p-value</th><th>Interpretation</th></tr></thead><tbody>{(caseResult.pareto||[]).map((p,i)=><tr key={`pareto-${i}`}><td>{p.category}</td><td>{p.count} defects · {(p.share*100).toFixed(1)}%</td><td>Pareto · baseline</td><td>—</td><td>Observed defect count, not causal evidence.</td></tr>)}{(caseResult.production_context_associations||[]).slice(0,12).map((a,i)=><tr key={`assoc-${i}`}><td>{a.factor}</td><td>{a.levels?.slice(0,3).map(g=>`${g.group}: ${(g.defect_rate*100).toFixed(1)}% (n=${g.n})`).join('; ') || `Defect mean ${a.defect_mean}; conforming mean ${a.conforming_mean}`}</td><td>{a.test} · {a.source}</td><td>{a.p_value}</td><td>{a.interpretation}</td></tr>)}</tbody></table></div>{(caseResult.root_cause_hypotheses||[]).length > 0 && <div className="assumption-box"><strong>Hypotheses to verify</strong><ul>{caseResult.root_cause_hypotheses.map((h,i)=><li key={i}>{h.hypothesis} {h.evidence} <em>Hypothesis only.</em></li>)}</ul></div>}</Card>
              <Card><div className="card-heading"><div><h3>Analysis workpapers</h3><p>Key results used in the report. Full JSON and PDF exports contain detailed values.</p></div></div><div className="diagnostic-list"><div className="diagnostic"><span className="diagnostic-mark"><Gauge size={17}/></span><div><strong>Gauge R&amp;R</strong><p>{caseResult.measurement_system_analysis?.status === 'calculated' ? `Total gauge R&R ${caseResult.measurement_system_analysis.percent_study_variation?.total_gauge_rr}% of study variation; ndc estimate ${caseResult.measurement_system_analysis.ndc_estimate}.` : caseResult.measurement_system_analysis?.reason || 'No gauge study mapped.'}</p></div></div><div className="diagnostic"><span className="diagnostic-mark"><BarChart3 size={17}/></span><div><strong>2×2 improvement pilot</strong><p>{caseResult.improvement_pilot?.status === 'calculated' ? `Factorial effects estimated for ${caseResult.improvement_pilot.n} observations. See interaction and confidence intervals in report.` : caseResult.improvement_pilot?.reason || 'No pilot data mapped.'}</p></div></div><div className="diagnostic"><span className="diagnostic-mark"><Activity size={17}/></span><div><strong>Pre/post comparison</strong><p>{caseResult.pre_post_comparison ? `Observed defect rate ${((caseResult.pre_post_comparison.baseline_defect_rate||0)*100).toFixed(2)}% → ${((caseResult.pre_post_comparison.post_defect_rate||0)*100).toFixed(2)}%; difference ${caseResult.pre_post_comparison.absolute_reduction_percentage_points} percentage points. Not causal proof.` : 'No comparable baseline and post-change outcome detected.'}</p></div></div><div className="diagnostic"><span className="diagnostic-mark"><GitBranch size={17}/></span><div><strong>SPC / p-chart</strong><p>{caseResult.process_control?.status === 'calculated' ? `${caseResult.process_control.subgroups} subgroups; ${caseResult.process_control.signals_outside_limits?.length || 0} points outside 3-sigma limits.` : caseResult.process_control?.reason || 'No subgroup data mapped.'}</p></div></div><div className="diagnostic"><span className="diagnostic-mark"><Database size={17}/></span><div><strong>Financial forecast</strong><p>{caseResult.financial_forecast?.status === 'forecast_only' ? `Gross annual savings forecast ₹${Number(caseResult.financial_forecast.gross_annual_savings_forecast_inr).toLocaleString('en-IN')}; not realized savings.` : caseResult.financial_forecast?.note || 'No complete financial assumptions supplied.'}</p></div></div></div></Card>
              <Card><div className="card-heading"><div><h3>Prioritized team action plan</h3><p>Each action has a responsible role and concrete closure evidence.</p></div></div>{(caseResult.recommended_actions||[]).map((a,i)=><div className="team-action" key={i}><div className="team-action-badge"><strong>{a.priority}</strong><Status>{a.phase}</Status></div><div className="team-action-body"><div className="team-action-meta">Suggested owner: {a.owner}</div><h4>{a.action}</h4><small><strong>Closure evidence:</strong> {a.completion_evidence}</small></div></div>)}</Card>
              <Card><div className="card-heading"><div><h3>Limitations and assumptions</h3><p>Do not make decisions until these have been reviewed.</p></div></div><ul>{(caseResult.limitations||[]).map((x,i)=><li key={i} className="limitation-item">{x}</li>)}</ul></Card>
            </>}
          </div><div className="agent-side"><Card><div className="card-heading"><div><h3>What this run does</h3><p>One prompt, one evidence pack, a connected DMAIC work product.</p></div></div><div className="workflow-steps">{['Read charter, prompt, dictionary and reference files','Map datasets to baseline, context, MSA, pilot, post-change, SPC and finance','Validate defect flags and calculate supported statistics','Separate evidence from hypotheses and recommendations','Create DMAIC phase gates, action plan and report exports'].map((x,i)=><div className="workflow-step" key={i}><div className="workflow-step-icon">{i+1}</div><div><strong>{['Understand the case','Map all files','Calculate and cross-check','Challenge the evidence','Deliver an actionable report'][i]}</strong><p>{x}</p></div></div>)}</div></Card><Card className="info-card"><div className="info-heading"><ShieldCheck size={18}/><strong>Non-negotiable evidence rules</strong></div><ul><li>Raw data outranks an unsupported narrative claim.</li><li>Defect flags are reconciled to supplied specifications.</li><li>Associations are hypotheses, not causal proof.</li><li>Gauge R&amp;R needs a valid crossed study design.</li><li>Financial benefit is forecast until Finance validates realized results.</li><li>Missing files and uncalculated metrics are stated, not invented.</li></ul></Card></div></div>
        </>}

        {page === 'analysis' && <>
          <SectionTitle eyebrow="MEASURE · ANALYZE" title="Data & process analysis" detail="Import a real dataset, choose the measurement and specifications, then inspect the calculations and their assumptions." action={<label className="button button-primary file-button"><UploadCloud size={17}/> Upload data<input type="file" accept=".csv,.xlsx,.xls" onChange={e => onUpload(e.target.files?.[0])}/></label>}/>
          <div className="analysis-layout"><div className="analysis-main-col">
            <Card><div className="card-heading"><div><h3>Import or connect data</h3><p>Paste a CSV manually or import a read-only HTTPS JSON endpoint. Connector tokens are used once and not saved.</p></div><span className="step-number">SOURCE</span></div><div className="source-import-grid"><form className="source-import-panel" onSubmit={importManualData}><div className="source-panel-title"><Database size={16}/><strong>Manual CSV input</strong></div><Field label="Dataset filename"><input value={manualFilename} onChange={e=>setManualFilename(e.target.value)} required/></Field><Field label="Paste CSV content"><textarea value={manualCSV} onChange={e=>setManualCSV(e.target.value)} rows="5" placeholder="measurement,shift,defects\n10.2,A,0\n9.8,B,1" required/></Field><button className="button button-secondary button-small" disabled={busy || !manualCSV.trim()}><Plus size={14}/> Import pasted data</button></form><form className="source-import-panel" onSubmit={importConnector}><div className="source-panel-title"><GitBranch size={16}/><strong>Read-only HTTPS JSON</strong></div><Field label="JSON endpoint URL"><input type="url" value={connectorUrl} onChange={e=>setConnectorUrl(e.target.value)} placeholder="https://api.example.com/records" required/></Field><Field label="Bearer token (optional)"><input type="password" autoComplete="off" value={connectorToken} onChange={e=>setConnectorToken(e.target.value)} placeholder="Token is not persisted"/></Field><Field label="Save as dataset"><input value={connectorFilename} onChange={e=>setConnectorFilename(e.target.value)} required/></Field><button className="button button-secondary button-small" disabled={busy || !connectorUrl.trim()}><ArrowDownToLine size={14}/> Import endpoint</button><small>HTTPS only · public hosts only · 5 MB response cap · redirects blocked</small></form></div></Card>
            <Card><div className="card-heading"><div><h3>1. Select a dataset</h3><p>Data is stored locally and never sent to an AI provider by default.</p></div><span className="step-number">01</span></div>{datasets.length ? <><Field label="Dataset"><select value={selectedDataset} onChange={e => {setSelectedDataset(e.target.value);setAnalysis(null);const ds=datasets.find(x=>x.id===e.target.value);setAnalysisConfig(c=>({...c,value_column:ds?.columns?.[0]||''}));}}>{datasets.map(d=><option value={d.id} key={d.id}>{d.filename} · {d.row_count.toLocaleString()} rows</option>)}</select></Field>{currentDataset && <div className="dataset-info"><div className="dataset-file"><FileText size={20}/></div><div><strong>{currentDataset.filename}</strong><span>{currentDataset.row_count.toLocaleString()} rows · {currentDataset.columns.length} columns · {currentDataset.file_type.toUpperCase()}</span></div><Status>Local</Status></div>}</> : <Empty icon={UploadCloud} title="No data uploaded yet" detail="Upload a CSV or Excel file to begin a reproducible analysis."/>}</Card>
            <Card><div className="card-heading"><div><h3>2. Configure analysis</h3><p>Use approved specifications and correct units. Leave limits blank when they are unknown.</p></div><span className="step-number">02</span></div><div className="form-grid"><Field label="Measurement column"><select value={analysisConfig.value_column} onChange={e=>setAnalysisConfig(c=>({...c,value_column:e.target.value}))} disabled={!currentDataset}><option value="">Select numeric column</option>{numericColumns.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Lower specification limit (LSL)"><input type="number" value={analysisConfig.lsl} onChange={e=>setAnalysisConfig(c=>({...c,lsl:e.target.value}))} placeholder="Optional"/></Field><Field label="Upper specification limit (USL)"><input type="number" value={analysisConfig.usl} onChange={e=>setAnalysisConfig(c=>({...c,usl:e.target.value}))} placeholder="Optional"/></Field><Field label="Defective-unit flag (optional)"><select value={analysisConfig.defective_column} onChange={e=>setAnalysisConfig(c=>({...c,defective_column:e.target.value}))}><option value="">Not used</option>{numericColumns.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Defect count column (optional)"><select value={analysisConfig.defect_count_column} onChange={e=>setAnalysisConfig(c=>({...c,defect_count_column:e.target.value}))}><option value="">Not used</option>{numericColumns.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Opportunities per unit"><input type="number" min="1" value={analysisConfig.opportunities_per_unit} onChange={e=>setAnalysisConfig(c=>({...c,opportunities_per_unit:e.target.value}))} placeholder="Needed for DPMO"/></Field><Field label="Group column (optional)"><select value={analysisConfig.group_column} onChange={e=>setAnalysisConfig(c=>({...c,group_column:e.target.value}))}><option value="">No group comparison</option>{numericColumns.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Group A value"><input value={analysisConfig.group_a} onChange={e=>setAnalysisConfig(c=>({...c,group_a:e.target.value}))} placeholder="Exact group value"/></Field><Field label="Group B value"><input value={analysisConfig.group_b} onChange={e=>setAnalysisConfig(c=>({...c,group_b:e.target.value}))} placeholder="Exact group value"/></Field></div><div className="form-note"><CircleHelp size={15}/><span>Capability indices use an average-moving-range estimate for within-process variation. Stability and distribution suitability must be reviewed separately.</span></div><button className="button button-primary" onClick={runAnalysis} disabled={busy || !currentDataset || !analysisConfig.value_column}><Activity size={17}/>{busy ? 'Running…' : 'Run statistical analysis'}</button></Card>
            {analysis && <Card className="results-card"><div className="card-heading"><div><h3>Calculated results</h3><p>{currentDataset?.filename || 'Selected dataset'} · {new Date(analysis.created_at).toLocaleString()}</p></div><DownloadLink href={`${API}/reports/analysis/${analysis.id}`}>Export report</DownloadLink></div><div className="result-grid"><Metric label="Observations (n)" value={analysis.result.n}/><Metric label="Mean" value={analysis.result.mean}/><Metric label="Median" value={analysis.result.median}/><Metric label="Sample std. dev." value={analysis.result.sample_std_dev}/></div>{analysis.result.data_quality && <div className="assumption-box"><strong>Raw-data quality audit · {analysis.result.data_quality.status}</strong><p>{analysis.result.data_quality.row_count} raw rows · {analysis.result.data_quality.exact_duplicate_rows} exact duplicate rows retained · {analysis.result.data_quality.measurement?.valid_finite_numeric_count} valid finite measurements · {analysis.result.data_quality.measurement?.invalid_or_missing_count} missing/invalid measurements.</p><ul>{(analysis.result.data_quality.warnings||[]).map((warning,i)=><li key={i}>{warning}</li>)}</ul><p>{analysis.result.data_quality.scope_note}</p></div>}{analysis.result.calculation_validation && <div className="assumption-box"><strong>Calculation cross-check · {analysis.result.calculation_validation.status}</strong><p>{analysis.result.calculation_validation.failed_check_count} failed arithmetic check(s). These checks independently recompute selected metrics; they do not validate every statistical assumption.</p><ul>{(analysis.result.calculation_validation.checks||[]).map((check,i)=><li key={i}><strong>{check.metric}: {check.status}</strong>{check.status==='failed' ? ` — reported ${check.reported}; recomputed ${check.independently_recomputed}` : ''}</li>)}</ul></div>}<div className="result-details"><div><h4>Distribution and range</h4><div className="detail-pairs"><span>Minimum</span><strong>{analysis.result.min}</strong><span>Maximum</span><strong>{analysis.result.max}</strong><span>Q1 / Q3</span><strong>{analysis.result.q1} / {analysis.result.q3}</strong><span>95% CI for mean</span><strong>{analysis.result.mean_confidence_interval_95?.low ?? '—'} to {analysis.result.mean_confidence_interval_95?.high ?? '—'}</strong></div></div><div><h4>Specification / capability</h4>{analysis.result.specification ? <div className="detail-pairs"><span>Out of spec</span><strong>{analysis.result.specification.out_of_spec_count} ({(analysis.result.specification.out_of_spec_rate*100).toFixed(2)}%)</strong><span>Cp</span><strong>{analysis.result.specification.cp ?? 'Not calculated'}</strong><span>Cpk</span><strong>{analysis.result.specification.cpk ?? 'Not calculated'}</strong><span>Limits</span><strong>{analysis.result.specification.lsl} – {analysis.result.specification.usl}</strong></div> : <p className="muted-text">Add valid LSL and USL to calculate empirical out-of-spec rate and capability estimates.</p>}</div></div><div className="diagnostic-row"><div className="diagnostic"><span className="diagnostic-mark"><Activity size={17}/></span><div><strong>Normality diagnostic</strong><p>{analysis.result.normality?.interpretation || analysis.result.normality?.message || analysis.result.normality?.status}</p></div></div><div className="diagnostic"><span className="diagnostic-mark"><GitBranch size={17}/></span><div><strong>I-MR control chart</strong><p>{analysis.result.imr?.status === 'calculated' ? `${analysis.result.imr.individual_signals.length} individual-chart and ${analysis.result.imr.moving_range_signals.length} moving-range limit signals. Row order treated as process order.` : analysis.result.imr?.message}</p></div></div></div>{analysis.result.defects && <div className="assumption-box"><strong>Defect metrics</strong><p>Yield: {analysis.result.defects.yield ?? '—'} · Defects: {analysis.result.defects.defect_count ?? '—'} · DPMO: {analysis.result.defects.dpmo ?? '—'} · Sigma estimate: {analysis.result.defects.sigma_estimate ?? '—'}</p></div>}{analysis.result.group_comparison && <div className="group-result"><h4><BarChart3 size={16}/> Welch two-sample comparison</h4><div className="detail-pairs"><span>Group A mean (n)</span><strong>{analysis.result.group_comparison.mean_a} ({analysis.result.group_comparison.n_a})</strong><span>Group B mean (n)</span><strong>{analysis.result.group_comparison.mean_b} ({analysis.result.group_comparison.n_b})</strong><span>Mean difference A−B</span><strong>{analysis.result.group_comparison.difference_a_minus_b}</strong><span>p-value</span><strong>{analysis.result.group_comparison.p_value}</strong><span>95% CI for difference</span><strong>{analysis.result.group_comparison.confidence_interval?.low} to {analysis.result.group_comparison.confidence_interval?.high}</strong></div><p>{analysis.result.group_comparison.interpretation} This test does not establish causation.</p></div>}<div className="assumption-box"><strong><AlertTriangle size={15}/> Assumptions to review</strong><ul>{[...(analysis.result.evidence_notes||[]),...(analysis.result.specification?.assumptions||[]),...(analysis.result.defects?.assumptions||[])].map((x,i)=><li key={i}>{x}</li>)}</ul></div></Card>}
          </div><div className="analysis-side-col"><Card><div className="card-heading"><div><h3>Analysis toolbox</h3><p>Included deterministic methods</p></div></div><div className="tool-list"><div><span><Activity size={17}/></span><div><strong>Descriptive statistics</strong><p>Mean, median, spread, quartiles, missing values</p></div></div><div><span><Gauge size={17}/></span><div><strong>Process capability</strong><p>Cp/Cpk, when specifications are provided</p></div></div><div><span><GitBranch size={17}/></span><div><strong>SPC diagnostic</strong><p>Basic I-MR limits and signals</p></div></div><div><span><BarChart3 size={17}/></span><div><strong>Defect analysis</strong><p>Yield, DPMO, convention-based sigma estimate</p></div></div></div></Card><Card className="info-card"><div className="info-heading"><ShieldCheck size={18}/><strong>Statistical integrity</strong></div><p>Calculations are performed in Python. AI is not used to generate metrics, p-values, control limits, or capability indices.</p><div className="info-foot"><CheckCircle2 size={15}/> Calculations reproducible from source data</div></Card><Card><div className="card-heading"><div><h3>Latest analyses</h3><p>Saved runs — select to reopen</p></div></div>{analysisRuns.length ? <div className="saved-analysis-list">{analysisRuns.slice(0,8).map(saved=><button className={`saved-analysis ${analysis?.id===saved.id?'selected':''}`} key={saved.id} onClick={()=>openAnalysis(saved.id)}><span className="recent-icon"><BarChart3 size={16}/></span><span><strong>{saved.config.value_column}</strong><small>{saved.filename || 'Dataset'} · n={saved.result.n}</small><small>{new Date(saved.created_at).toLocaleString()}</small></span><ChevronRight size={15}/></button>)}</div> : <p className="muted-text">Run an analysis to save a reproducible result and report.</p>}</Card></div></div>
        </>}

        {page === 'projects' && <>
          <SectionTitle eyebrow="DEFINE → CONTROL" title="DMAIC project management" detail="Create a charter, track the current phase, and keep decisions, actions, risks, and evidence in one persistent log." action={<span className="live-pill"><Layers3 size={14}/> {projects.length} PROJECTS</span>}/>
          <div className="project-layout"><div className="project-list-col"><Card><div className="card-heading"><div><h3>Your projects</h3><p>Select a project to review its charter and log</p></div></div>{projects.length ? <div className="project-list">{projects.map(p=><button key={p.id} className={`project-list-item ${selectedProject===p.id?'selected':''}`} onClick={()=>setSelectedProject(p.id)}><div className="project-avatar">{p.name.slice(0,1).toUpperCase()}</div><div className="project-list-copy"><strong>{p.name}</strong><span>{p.process_name || 'Process not specified'}</span><div className="project-list-meta"><Status>{p.status}</Status><span>{p.priority} priority</span></div></div><ChevronRight size={16}/></button>)}</div> : <Empty icon={Workflow} title="No projects yet" detail="Create your first project using the form."/>}</Card><Card><div className="card-heading"><div><h3>New project charter</h3><p>Start with a problem and a measurable goal</p></div><Plus size={18}/></div><form className="stack-form" onSubmit={createProject}><Field label="Project name"><input required minLength="2" value={projectForm.name} onChange={e=>setProjectForm(f=>({...f,name:e.target.value}))} placeholder="e.g. Reduce order processing time"/></Field><Field label="Process / team"><input value={projectForm.process_name} onChange={e=>setProjectForm(f=>({...f,process_name:e.target.value}))} placeholder="e.g. Order fulfillment"/></Field><Field label="Problem statement"><textarea rows="3" value={projectForm.problem_statement} onChange={e=>setProjectForm(f=>({...f,problem_statement:e.target.value}))} placeholder="What is happening, where, and why does it matter?"/></Field><Field label="Goal statement"><textarea rows="2" value={projectForm.goal_statement} onChange={e=>setProjectForm(f=>({...f,goal_statement:e.target.value}))} placeholder="Target, baseline, and timeframe (if known)"/></Field><div className="form-grid"><Field label="Owner"><input value={projectForm.owner} onChange={e=>setProjectForm(f=>({...f,owner:e.target.value}))} placeholder="Owner"/></Field><Field label="Priority"><select value={projectForm.priority} onChange={e=>setProjectForm(f=>({...f,priority:e.target.value}))}>{['Low','Medium','High','Critical'].map(x=><option key={x}>{x}</option>)}</select></Field></div><Field label="Target date"><input type="date" value={projectForm.target_date} onChange={e=>setProjectForm(f=>({...f,target_date:e.target.value}))}/></Field><button className="button button-primary" disabled={busy}><Plus size={16}/> Create DMAIC project</button></form></Card></div>
            <div className="project-detail-col">{currentProject ? <><Card><div className="project-detail-top"><div><div className="eyebrow">PROJECT CHARTER</div><h2>{currentProject.name}</h2><p>{currentProject.process_name || 'Process not specified'} · Owner: {currentProject.owner || 'Unassigned'}</p></div><Status>{currentProject.status}</Status></div><div className="dmaic-track">{PHASES.map((ph,i)=><button key={ph} className={`dmaic-step ${currentProject.status===ph?'current':''} ${PHASES.indexOf(currentProject.status)>i?'passed':''}`} onClick={()=>runBusy(async()=>{const updated=await request(`/projects/${currentProject.id}`,jsonOptions('PATCH',{status:ph}));setProjects(ps=>ps.map(p=>p.id===updated.id?updated:p));},`Project moved to ${ph}.`)}><span>{PHASES.indexOf(currentProject.status)>i ? <CheckCircle2 size={16}/> : i+1}</span><strong>{ph}</strong></button>)}</div><div className="charter-grid"><div><span>Problem statement</span><p>{currentProject.problem_statement || 'Not documented yet.'}</p></div><div><span>Goal statement</span><p>{currentProject.goal_statement || 'Not documented yet.'}</p></div><div><span>Priority</span><p>{currentProject.priority}</p></div><div><span>Target date</span><p>{currentProject.target_date || 'Not set'}</p></div></div></Card><Card><div className="card-heading"><div><h3>Project evidence log</h3><p>Every entry is timestamped and linked to a DMAIC phase</p></div><span className="count-pill">{currentProject.entries?.length || 0} entries</span></div><form className="entry-form" onSubmit={addEntry}><div className="form-grid"><Field label="DMAIC phase"><select value={entryForm.phase} onChange={e=>setEntryForm(f=>({...f,phase:e.target.value}))}>{PHASES.map(p=><option key={p}>{p}</option>)}</select></Field><Field label="Entry type"><select value={entryForm.entry_type} onChange={e=>setEntryForm(f=>({...f,entry_type:e.target.value}))}>{['note','decision','action','risk','metric','hypothesis'].map(x=><option key={x}>{x}</option>)}</select></Field></div><Field label="Title"><input required minLength="2" value={entryForm.title} onChange={e=>setEntryForm(f=>({...f,title:e.target.value}))} placeholder="Short, specific title"/></Field><Field label="Details / evidence"><textarea required rows="3" value={entryForm.content} onChange={e=>setEntryForm(f=>({...f,content:e.target.value}))} placeholder="Record the observation, decision, owner, or next action. Distinguish facts from hypotheses."/></Field><button className="button button-primary" disabled={busy}><Plus size={15}/> Add log entry</button></form><div className="entry-timeline">{(currentProject.entries||[]).length ? currentProject.entries.map(entry=><div className="timeline-item" key={entry.id}><span className="timeline-dot"/><div className="timeline-body"><div className="timeline-meta"><Status>{entry.phase}</Status><span>{entry.entry_type}</span><time>{new Date(entry.created_at).toLocaleString()}</time></div><strong>{entry.title}</strong><p>{entry.content}</p></div></div>) : <Empty icon={BookOpenCheck} title="No log entries yet" detail="Add the first observation or decision above."/>}</div></Card></> : <Card><Empty icon={Workflow} title="Select a DMAIC project" detail="Create a project or choose one from the list to manage its lifecycle."/></Card>}</div></div>
        </>}

        {page === 'agent' && <>
          <SectionTitle eyebrow="AI-ASSISTED DMAIC" title="Process improvement analyst" detail="A bounded Define–Measure–Analyze–Improve–Control workflow with persisted traces, deterministic findings, and optional hosted-model interpretation." action={<span className={`provider-pill ${health?.llm_configured?'provider-on':''}`}><span className="state-dot"/>{health?.llm_configured?'Hosted model ready':'Template mode · no API key'}</span>}/>
          <div className="agent-layout"><div className="agent-main"><Card className="agent-run-card"><div className="agent-heading"><div className="agent-spark"><Sparkles size={23}/></div><div><h3>Start an improvement run</h3><p>The agent uses a bounded workflow and records each stage. It cannot claim a cause or improvement without supporting evidence.</p></div></div><form className="stack-form" onSubmit={runAgent}><Field label="Project context"><select value={selectedProject} onChange={e=>setSelectedProject(e.target.value)}><option value="">No project selected</option>{projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Dataset"><select value={selectedDataset} onChange={e=>setSelectedDataset(e.target.value)}><option value="">No dataset selected</option>{datasets.map(d=><option key={d.id} value={d.id}>{d.filename}</option>)}</select></Field><Field label="Analysis run"><div className="selected-analysis">{analysis ? <><CheckCircle2 size={16}/><span>{analysis.config.value_column} · {analysis.result.n} observations · {analysis.id.slice(0,8)}</span></> : <><CircleHelp size={16}/><span>No analysis run selected in this session. If a dataset has numeric columns, the agent can use its first numeric column for baseline metrics.</span></>}</div></Field><Field label="Improvement question"><textarea rows="4" value={agentPrompt} onChange={e=>setAgentPrompt(e.target.value)} placeholder="What do you need to understand or improve?"/></Field><button className="button button-primary button-wide" disabled={busy || (!selectedProject && !selectedDataset)}><Sparkles size={17}/>{busy ? 'Running bounded DMAIC workflow…' : 'Run DMAIC analyst'}</button><div className="form-footnote"><ShieldCheck size={14}/> No API key required for deterministic mode. Add a key later to enable hosted AI interpretation.</div></form></Card>
            {agentResult && <><Card className="agent-result-card"><div className="card-heading"><div><div className="eyebrow">RUN RESULTS</div><h3>Evidence and interpretation</h3><p>Run {agentResult.run_id?.slice(0,8)} · {agentResult.completed_stages?.length || 0} steps recorded</p></div><div className="heading-actions">{agentResult.status==='failed' && <button className="button button-secondary button-small" onClick={()=>resumeAgent(agentResult.run_id)} disabled={busy}><RefreshCw size={14}/> Resume</button>}<DownloadLink href={`${API}/reports/agent/${agentResult.run_id}`}>Export report</DownloadLink></div></div><div className="evidence-section"><h4><ShieldCheck size={16}/> Verified findings</h4><p className="section-subtext">Deterministic values calculated from the selected dataset.</p>{(agentResult.verified_findings||[]).length ? <div className="finding-list">{agentResult.verified_findings.map(f=><div className="finding-item" key={f.id}><span className="finding-check"><CheckCircle2 size={16}/></span><div><p>{f.text}</p><span>{f.kind} · source {f.source}</span>{f.assumption && <small>{f.assumption}</small>}</div></div>)}</div> : <div className="empty compact"><strong>No measured findings attached</strong><p>Connect a dataset and run a statistical analysis for data-grounded findings.</p></div>}</div><div className="interpretation-section"><h4><Sparkles size={16}/> AI interpretation <span className="not-verified">NOT A VERIFIED FINDING</span></h4><p>{agentResult.ai_interpretation?.summary || 'No AI interpretation returned.'}</p><div className="interpretation-grid">{[['Hypotheses',agentResult.ai_interpretation?.hypotheses],['Recommendations',agentResult.ai_interpretation?.recommendations],['Risks',agentResult.ai_interpretation?.risks]].map(([title,items])=><div className="interpretation-box" key={title}><strong>{title}</strong><ul>{(items||[]).map((x,i)=><li key={i}>{x}</li>)}</ul></div>)}</div><div className="provider-note">Source: {agentResult.ai_interpretation?.provider_status || 'unknown'} · {agentResult.ai_interpretation?.evidence_policy || 'Interpretation is not independently verified.'}</div></div></Card><Card><div className="card-heading"><div><h3>Execution trace</h3><p>Each workflow step is persisted for review and recovery</p></div><Status>{agentResult.status || 'completed'}</Status></div><div className="run-trace">{(agentResult.trace||[]).map((step,i)=><div className="trace-row" key={`${step.stage}-${i}`}><span className={`trace-icon ${step.status==='completed'?'trace-ok':''}`}>{step.status==='completed'?<CheckCircle2 size={16}/>:<Activity size={16}/>}</span><div><strong>{step.stage}</strong><p>{step.message}</p>{step.deliverables?.length>0 && <ul>{step.deliverables.map((d,j)=><li key={j}>{d}</li>)}</ul>}</div><span className="trace-index">{String(i+1).padStart(2,'0')}</span></div>)}</div></Card></>}
          </div><div className="agent-side"><Card><div className="card-heading"><div><h3>Bounded workflow</h3><p>Stages are explicit and traceable</p></div></div><div className="workflow-steps">{PHASES.map((phase,i)=><div className="workflow-step" key={phase}><div className={`workflow-step-icon ${agentResult?.completed_stages?.includes(phase)?'done':''}`}>{agentResult?.completed_stages?.includes(phase)?<CheckCircle2 size={16}/>:i+1}</div><div><strong>{phase}</strong><p>{['Scope the problem and define the objective','Review data quality and establish a baseline','Separate calculated signals from cause hypotheses','Design a measurable pilot rather than claiming success','Set monitoring, ownership, and escalation criteria'][i]}</p></div></div>)}</div></Card><Card className="info-card"><div className="info-heading"><Bot size={18}/><strong>Model settings</strong></div><p>Hosted model calls use an OpenAI-compatible chat-completions endpoint. Configure your API key and model in the backend environment file when ready.</p><div className="settings-list"><div><span>Provider</span><strong>{health?.llm_configured?'Configured':'Not configured'}</strong></div><div><span>Fallback</span><strong>Deterministic template</strong></div><div><span>Evidence</span><strong>Local calculations</strong></div></div><div className="info-foot"><ShieldCheck size={15}/> Keys are read by the backend only</div></Card><Card><div className="card-heading"><div><h3>Previous runs</h3><p>Open a saved trace</p></div></div>{agentRuns.length ? agentRuns.slice(0,7).map(run=><button className="past-run" key={run.id} onClick={()=>openRun(run.id)}><span className="past-run-icon"><Bot size={15}/></span><span><strong>{run.id.slice(0,8)}</strong><small>{new Date(run.created_at).toLocaleString()}</small></span><Status>{run.status}</Status></button>) : <p className="muted-text">Completed and failed runs will be stored here.</p>}</Card></div></div>
        </>}

        {page === 'team' && <>
          <SectionTitle eyebrow="CROSS-FUNCTIONAL IMPROVEMENT OFFICE" title="Your virtual Six Sigma team" detail="One coordinated review across nine specialist roles, with DMAIC stage gates, a prioritized action register, RACI, risks, and exportable deliverables. The software simulates team perspectives; it does not impersonate actual approvals or replace accountable human decisions." action={<span className={`provider-pill ${health?.llm_configured?'provider-on':''}`}><span className="state-dot"/>{health?.llm_configured?'Model available · optional':'Evidence-led mode'}</span>}/>
          <div className="agent-layout"><div className="agent-main">
            <Card className="agent-run-card"><div className="agent-heading"><div className="agent-spark"><Users size={23}/></div><div><h3>Convene the full virtual team</h3><p>Project leadership, process expertise, statistics, measurement systems, root cause, finance, change, and control ownership work from the same evidence pack.</p></div></div>
              <form className="stack-form" onSubmit={runTeamReview}>
                <Field label="DMAIC project"><select value={selectedProject} onChange={e=>setSelectedProject(e.target.value)}><option value="">No project selected</option>{projects.map(p=><option key={p.id} value={p.id}>{p.name} · {p.status}</option>)}</select></Field>
                <Field label="Dataset"><select value={selectedDataset} onChange={e=>setSelectedDataset(e.target.value)}><option value="">No dataset selected</option>{datasets.map(d=><option key={d.id} value={d.id}>{d.filename} · {d.row_count} rows</option>)}</select></Field>
                <Field label="Saved analysis"><select value={analysis?.id || ''} onChange={async e=>{try { if(e.target.value) { const saved = await request(`/analysis/${e.target.value}`); setAnalysis(saved); setSelectedDataset(saved.dataset_id); } else setAnalysis(null); } catch(err) { setError(err.message); } }}><option value="">Use no saved analysis</option>{analysisRuns.map(a=><option key={a.id} value={a.id}>{a.filename} · {a.config?.value_column || 'analysis'} · {a.id.slice(0,8)}</option>)}</select><small>For capability or defect findings, run Data &amp; Analysis first and select the saved result.</small></Field>
                <Field label="Team brief / question"><textarea rows="4" value={teamQuestion} onChange={e=>setTeamQuestion(e.target.value)} /></Field>
                <button className="button button-primary button-wide" disabled={busy || (!selectedProject && !selectedDataset && !analysis)}><Users size={17}/>{busy ? 'Convening specialist roles…' : 'Run full team review'}</button>
                <div className="form-footnote"><ShieldCheck size={14}/> No API key is required for the structured review. A configured model can be used for broader language analysis in the AI Analyst, but it cannot approve gates or invent evidence.</div>
              </form>
            </Card>
            {teamReview && <>
              <Card><div className="card-heading"><div><div className="eyebrow">TEAM BRIEF · {teamReview.review_id.slice(0,8)}</div><h3>Executive review</h3><p>{teamReview.created_at ? new Date(teamReview.created_at).toLocaleString() : ''}</p></div><div className="heading-actions"><DownloadLink href={`${API}/reports/team/${teamReview.review_id}?format=markdown`}>Markdown</DownloadLink><DownloadLink href={`${API}/reports/team/${teamReview.review_id}?format=pdf`}>PDF</DownloadLink><DownloadLink href={`${API}/reports/team/${teamReview.review_id}?format=json`}>JSON</DownloadLink></div></div><p>{teamReview.executive_summary}</p><div className="audit-disclaimer"><AlertTriangle size={15}/><span>{teamReview.team_model}</span></div><div className="metric-grid"><Metric label="DMAIC gates ready for review" value={`${(teamReview.dmaic_gates||[]).filter(g=>g.status==='ready_for_review').length}/5`} sub="Not automatically approved" icon={Workflow}/><Metric label="Prioritized actions" value={(teamReview.action_register||[]).length} sub="Assigned by role" icon={ListChecks}/><Metric label="Open blockers" value={(teamReview.blockers||[]).length} sub="Evidence or charter gaps" icon={AlertTriangle}/><Metric label="Virtual specialists" value={(teamReview.team_members||[]).length} sub="Cross-functional viewpoints" icon={Users}/></div></Card>
              <Card className="agent-result-card"><div className="card-heading"><div><h3>Cross-functional synthesis</h3><p>Optional model interpretation grounded in the project summary, dataset profile, calculated metrics, gates, and action plan.</p></div><span className="not-verified">NOT VERIFIED EVIDENCE</span></div><p className="team-synthesis-summary">{teamReview.ai_team_synthesis?.summary || 'No synthesis summary returned.'}</p><div className="interpretation-grid">{[['Hypotheses',teamReview.ai_team_synthesis?.hypotheses],['Recommendations',teamReview.ai_team_synthesis?.recommendations],['Risks',teamReview.ai_team_synthesis?.risks]].map(([title,items])=><div className="interpretation-box" key={title}><strong>{title}</strong><ul>{(items||[]).map((x,i)=><li key={i}>{x}</li>)}</ul></div>)}</div><div className="provider-note">Source: {teamReview.ai_team_synthesis?.provider_status || 'unknown'} · {teamReview.ai_team_synthesis?.evidence_policy || 'Advisory only; not independently verified.'}</div></Card>
              <Card><div className="card-heading"><div><h3>Specialist stand-up</h3><p>Role-based assessments and what each function is responsible for</p></div><span className="count-pill">{teamReview.team_members?.length || 0} roles</span></div><div className="team-role-grid">{(teamReview.team_members||[]).map(member=><div className="team-role-card" key={member.role}><div className="team-role-top"><span className="team-role-icon"><Users size={17}/></span><Status>{member.status}</Status></div><h4>{member.role}</h4><div className="eyebrow">{member.focus}</div><p>{member.assessment}</p><strong>Responsibilities</strong><ul>{(member.responsibilities||[]).map((item,i)=><li key={i}>{item}</li>)}</ul><strong>Watchouts</strong><ul>{(member.watchouts||[]).map((item,i)=><li key={i}>{item}</li>)}</ul></div>)}</div></Card>
              <Card><div className="card-heading"><div><h3>DMAIC stage-gate review</h3><p>Every unmet item blocks a clean handoff until evidence is supplied and a human reviews it.</p></div></div><div className="team-gates">{(teamReview.dmaic_gates||[]).map(gate=><div className="team-gate" key={gate.phase}><div className="team-gate-header"><div><span className="step-number">{PHASES.indexOf(gate.phase)+1}</span><h4>{gate.phase}</h4></div><Status>{gate.status.replaceAll('_',' ')}</Status></div><div className="gate-criteria">{gate.criteria.map(c=><div className={`gate-criterion ${c.met?'gate-met':'gate-missing'}`} key={c.item}><span>{c.met?'✓':'!'}</span>{c.item}</div>)}</div><p>{gate.decision}</p></div>)}</div></Card>
              <Card><div className="card-heading"><div><h3>Prioritized action register</h3><p>Each action includes a suggested role owner and evidence required to close it.</p></div><span className="count-pill">{teamReview.action_register?.length || 0} actions</span></div><div className="team-action-list">{(teamReview.action_register||[]).map(action=><div className="team-action" key={action.id}><div className="team-action-badge"><strong>{action.id}</strong><Status>{action.priority}</Status><select aria-label={`Update ${action.id} status`} value={action.status} disabled={busy} onChange={e=>updateTeamAction(action.id,e.target.value)}><option value="not_started">Not started</option><option value="in_progress">In progress</option><option value="blocked">Blocked</option><option value="completed">Completed</option></select></div><div className="team-action-body"><div className="team-action-meta">{action.phase} · Suggested owner: {action.owner_role}</div><h4>{action.task}</h4><p>{action.rationale}</p><small><strong>Exit evidence:</strong> {action.exit_evidence}</small></div></div>)}</div></Card>
              <Card><div className="card-heading"><div><h3>Decision rights · RACI</h3><p>Suggested accountability map to take into a real team meeting.</p></div></div><div className="audit-table-wrap"><table className="audit-table"><thead><tr><th>Activity</th><th>Responsible</th><th>Accountable</th><th>Consulted</th><th>Informed</th></tr></thead><tbody>{(teamReview.raci||[]).map((r,i)=><tr key={i}><td>{r.activity}</td><td>{r.responsible}</td><td>{r.accountable}</td><td>{r.consulted}</td><td>{r.informed}</td></tr>)}</tbody></table></div><div className="audit-disclaimer"><AlertTriangle size={15}/><span>Do not treat this suggested RACI as an organizational assignment until the people named by role accept it.</span></div></Card>
            </>}
          </div><div className="agent-side"><Card><div className="card-heading"><div><h3>Virtual team roster</h3><p>Specialist viewpoints included in each review</p></div></div><div className="workflow-steps">{(teamReview?.team_members || [{role:'Executive Sponsor',focus:'Value and decision rights'},{role:'Master/Black Belt Project Lead',focus:'DMAIC governance'},{role:'Process Owner / Subject-Matter Expert',focus:'Process reality'},{role:'Data Analyst / Statistician',focus:'Data and inference'},{role:'Measurement Systems Analyst',focus:'Measurement validity'},{role:'Root-Cause / Quality Engineer',focus:'Hypothesis testing'},{role:'Finance / Benefits Analyst',focus:'Financial validation'},{role:'Change & Training Lead',focus:'Adoption and standard work'},{role:'Control Plan Owner',focus:'Sustainment'}]).map((m,i)=><div className="workflow-step" key={m.role}><div className="workflow-step-icon">{i+1}</div><div><strong>{m.role}</strong><p>{m.focus}</p></div></div>)}</div></Card><Card><div className="card-heading"><div><h3>Previous team reviews</h3><p>Open saved reviews</p></div></div>{teamHistory.length ? teamHistory.slice(0,8).map(r=><button className="past-run" key={r.id} onClick={()=>openTeamReview(r.id)}><span className="past-run-icon"><ClipboardCheck size={15}/></span><span><strong>{r.id.slice(0,8)}</strong><small>{new Date(r.created_at).toLocaleString()}</small></span></button>) : <p className="muted-text">Your team reviews will appear here.</p>}</Card><Card className="info-card"><div className="info-heading"><ShieldCheck size={18}/><strong>Governance rules</strong></div><ul><li>No invented savings or customer outcomes.</li><li>No root cause accepted without validation.</li><li>No phase auto-approved.</li><li>Improvement effectiveness needs post-change data.</li><li>Human sign-off required for safety, finance, and production changes.</li></ul></Card></div></div>
        </>}

        {page === 'evidence' && <>
          <SectionTitle eyebrow="DOCUMENTS · AUDIT" title="Evidence library & audit trail" detail="Upload source documents for local text extraction, search them, and review timestamped actions taken in the workspace." action={<label className="button button-primary file-button"><UploadCloud size={17}/> Add evidence file<input type="file" accept=".pdf,.docx,.txt,.md,.csv,.xlsx,.xls" onChange={e=>onUpload(e.target.files?.[0])}/></label>}/>
          <Card><div className="card-heading"><div><h3>Searchable evidence documents</h3><p>PDF, DOCX, TXT, Markdown, CSV, and Excel files supported</p></div><span className="count-pill">{documents.length} shown</span></div><form className="search-form" onSubmit={searchDocuments}><Search size={17}/><input value={documentQuery} onChange={e=>setDocumentQuery(e.target.value)} placeholder="Search filenames and extracted text…"/><button className="button button-secondary button-small">Search</button></form>{documents.length ? <div className="document-list">{documents.map(doc=><div className="document-item" key={doc.id}><div className="document-icon"><FileText size={19}/></div><div className="document-copy"><strong>{doc.filename}</strong><span>{doc.file_type.toUpperCase()} · {(doc.size_bytes/1024).toFixed(1)} KB · {new Date(doc.created_at).toLocaleDateString()}</span>{doc.preview && <p>{doc.preview}{doc.preview.length>=500?'…':''}</p>}</div><Status>Indexed</Status></div>)}</div> : <Empty icon={FileText} title="No matching evidence documents" detail="Upload a PDF, Word document, text file, or spreadsheet. Text extraction is local."/>}</Card>
          <Card><div className="card-heading"><div><h3>Audit trail</h3><p>Local event log for uploads, analyses, and project actions</p></div><span className="count-pill">{audit.length} events</span></div>{audit.length ? <div className="audit-table-wrap"><table className="audit-table"><thead><tr><th>Action</th><th>Entity</th><th>Details</th><th>Timestamp</th></tr></thead><tbody>{audit.map(item=><tr key={item.id}><td><strong>{item.action}</strong></td><td>{item.entity_type}<small>{item.entity_id.slice(0,10)}</small></td><td>{JSON.stringify(item.details)}</td><td>{new Date(item.created_at).toLocaleString()}</td></tr>)}</tbody></table></div> : <Empty icon={ClipboardList} title="No audit events yet" detail="The application will record important workspace actions."/>}<div className="audit-disclaimer"><AlertTriangle size={15}/><span>This is an application audit log, not a tamper-proof or cryptographically signed compliance log.</span></div></Card>
        </>}
      </div>
    </main>
  </div>;
}
